class Solution {
public:
    int minOperations(vector<vector<int>>& grid, int x) {
        int m = grid.size();
        int n = grid[0].size();
        int total = m * n;

        vector<int> vals;
        vals.reserve(total);
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                vals.push_back(grid[i][j]);
            }
        }

        int r = vals[0] % x;
        for (int v : vals) {
            if (v % x != r) return -1;
        }

        nth_element(vals.begin(), vals.begin() + total / 2, vals.end());
        int median = vals[total / 2];

        long long ops = 0;
        for (int v : vals) {
            ops += abs(v - median) / x;
        }

        return (int)ops;
    }
};
